/** Is a change good (+1), bad (−1) or neutral (0) for this measure? */
export const goodness = (m, delta) => (!m.better || typeof delta !== 'number' || !delta ? 0 : (delta > 0) === (m.better === 'up') ? 1 : -1);

// ---------------------------------------------------------------- chart definitions (Trends tab and the monthly report)
const COL = { navy: '#16325c', red: '#c0392b', tan: '#c0904d', teal: '#2a9d8f', blue: '#8fa8cc', grey: '#8a97a8', green: '#1e8e5a', purple: '#7d5ba6' };
