    dmgN: s('dmgN'), dmgValue: s('dmgValue'), units, dmgRate: units > 0 ? (s('dmgN') / units) * 10000 : '',
    regH: reg, otH: s('otH'), hours: s('hours'), otPct: reg > 0 ? s('otH') / reg : '', prodOp: avgW('rNc'), prodAll: avgW('rAll'), safety: s('safety'), recordable: s('recordable'), ncr: b === '6049' ? s('ncr') : '', wrAcr: b === '6021' ? s('wrAcr') : '', wrRolls: b === '6021' ? s('wrRolls') : '',
