//    is active nothing can put the unit back in service. Release needs the removal checks; removal by someone other
//    than the person who applied the lock needs the supervisor steps (OSHA 1910.147(e)(3)).
export const COLLS = ['mheAssets', 'mheHours', 'mheService', 'mheOperators', 'mheExceptions', 'mheConfig', 'employees', 'mheWorkOrders', 'mheInspections', 'mheDocs', 'mheLoto'];
